#include <iostream>
#include <memory>

class BinarySearchTree {
    struct Node {
        int value;
        std::unique_ptr<Node> left, right;

        explicit Node(int value) : value(value) {}
    };

    std::unique_ptr<Node> root;

    static void insert(std::unique_ptr<Node>& node, int value) {
        if (!node) {
            node = std::make_unique<Node>(value);
        } else if (value < node->value) {
            insert(node->left, value);
        } else if (value > node->value) {
            insert(node->right, value);
        }
        // Duplicate values are ignored.
    }

    static bool search(const Node* node, int value) {
        if (!node) return false;
        if (value == node->value) return true;

        return search(
            value < node->value ? node->left.get() : node->right.get(),
            value
        );
    }

    static void remove(std::unique_ptr<Node>& node, int value) {
        if (!node) return;

        if (value < node->value) {
            remove(node->left, value);
        } else if (value > node->value) {
            remove(node->right, value);
        } else if (!node->left) {
            auto replacement = std::move(node->right);
            node = std::move(replacement);
        } else if (!node->right) {
            auto replacement = std::move(node->left);
            node = std::move(replacement);
        } else {
            Node* successor = node->right.get();
            while (successor->left) {
                successor = successor->left.get();
            }
            node->value = successor->value;
            remove(node->right, successor->value);
        }
    }

    static void inorder(const Node* node) {
        if (!node) return;
        inorder(node->left.get());
        std::cout << node->value << ' ';
        inorder(node->right.get());
    }

public:
    void insert(int value) { insert(root, value); }
    bool search(int value) const { return search(root.get(), value); }
    void remove(int value) { remove(root, value); }

    void print() const {
        inorder(root.get());
        std::cout << '\n';
    }
};

int main() {
    BinarySearchTree tree;

    for (int value : {50, 30, 70, 20, 40, 60, 80}) {
        tree.insert(value);
    }

    tree.print(); // 20 30 40 50 60 70 80

    std::cout << std::boolalpha << tree.search(40) << '\n'; // true

    tree.remove(50);
    tree.print(); // 20 30 40 60 70 80
}
